"""EMS base class"""
from __future__ import absolute_import, division, print_function,\
    unicode_literals
from builtins import object
from abc import ABCMeta, abstractmethod
from future import standard_library
from future.utils import with_metaclass
standard_library.install_aliases()


class EmsBase(with_metaclass(ABCMeta, object)):

    TOOL = None

    @abstractmethod
    def setup_ems(self, config_device, **kwargs):
        """Setup ems"""

    @abstractmethod
    def configuration_manage(self, **kwargs):
        """configuration manage"""

    @abstractmethod
    def enb_configuration_should_be_discovered(self, **kwargs):
        """enodeB configuration should be discovered"""

    @abstractmethod
    def teardown_ems(self, **kwargs):
        """Teardown ems"""

    @classmethod
    def check_tool(cls, tool):
        """Check tool"""
        return tool == cls.TOOL
